package vn.rtr.aeris.crew02;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;import java.nio.channels.FileChannel;
/** Retained generations. Archive integrity is not source authentication or authority. */
public final class Workspaces {
 public static final int LIMIT=8*1024*1024;private final Path root;private String selected;private String staged=null,stagedDigest=null,exported=null;public String exportSha=null;
 public Workspaces(Path p)throws IOException{root=p;new DraftStore(root);Path cur=root.resolve("CURRENT");if(Files.exists(root.resolve("CURRENT.pending")))throw new IOException("Pending selection; explicit recovery required");if(Files.isSymbolicLink(cur)||(Files.exists(cur)&&Files.size(cur)>64))throw new IOException("Current pointer bound/type");selected=Files.exists(cur)?new String(Files.readAllBytes(cur),StandardCharsets.US_ASCII).trim():"initial";validId(selected);store().load();}
 private void validId(String id)throws IOException{if(!id.matches("initial|w-[a-f0-9-]{36}"))throw new IOException("Workspace id");}
 private void admit()throws IOException{int count=0;long bytes=0;try(java.util.stream.Stream<Path> walk=Files.walk(root)){java.util.Iterator<Path> it=walk.iterator();while(it.hasNext()){Path p=it.next();if(Files.isSymbolicLink(p))throw new IOException("Workspace symlink");if(Files.isRegularFile(p))bytes+=Files.size(p);if(p.getParent()!=null&&p.getParent().equals(root)&&Files.isDirectory(p))count++;}}if(count>=16||bytes+LIMIT>128L*1024*1024||root.toFile().getUsableSpace()<DraftStore.RESERVE+2L*LIMIT)throw new IOException("Workspace quota/reserve; no automatic cleanup");}public String id(){return selected;}public DraftStore sitl()throws IOException{return new DraftStore(root.resolve(selected).resolve("sitl"));}public DraftStore store()throws IOException{return new DraftStore(root.resolve(selected));}
 private static void syncDir(Path p)throws IOException{try(FileChannel c=FileChannel.open(p,StandardOpenOption.READ)){c.force(true);}}
 private static void put(Path p,byte[] b)throws IOException{try(FileChannel f=FileChannel.open(p,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS)){java.nio.ByteBuffer data=java.nio.ByteBuffer.wrap(b);while(data.hasRemaining())if(f.write(data)==0)throw new IOException("Short workspace write");f.force(true);}}
 public static byte[] bounded(InputStream in)throws IOException{try(InputStream i=in;ByteArrayOutputStream o=new ByteArrayOutputStream()){if(i==null)throw new IOException("No stream");byte[] b=new byte[8192];int n;while((n=i.read(b))!=-1){if(o.size()+n>LIMIT)throw new IOException("Archive bound");o.write(b,0,n);}return o.toByteArray();}}
 public byte[] archive()throws IOException{DraftStore s=store();DraftStore.Snapshot head=s.load();if(head==null||s.pending())throw new IOException("Confirmed nonpending workspace required");ArrayList<Path> files=new ArrayList<>();try(DirectoryStream<Path>d=Files.newDirectoryStream(root.resolve(selected))){for(Path p:d){String n=p.getFileName().toString();if(n.equals("HEAD")||n.endsWith(".bin"))files.add(p);else if(n.equals("sitl")&&Files.isDirectory(p)){DraftStore a=sitl();if(a.pending())throw new IOException("Pending SITL journal");a.load();try(DirectoryStream<Path> q=Files.newDirectoryStream(p)){for(Path f:q){String k=f.getFileName().toString();if(k.equals("HEAD")||k.endsWith(".bin"))files.add(f);else if(!k.equals("LOCK"))throw new IOException("Unknown SITL entry");}}}else if(!n.equals("LOCK"))throw new IOException("Pending/unknown entry");}}Collections.sort(files);StringBuilder manifest=new StringBuilder("AERISARCHIVE83\n"+head.token+"\nauthority=false\n");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(bytes)){for(Path p:files){if(Files.isSymbolicLink(p)||!Files.isRegularFile(p)||Files.size(p)>DraftStore.MAX_BODY+512)throw new IOException("Entry bound");byte[] b=Files.readAllBytes(p);String archiveName=(p.getParent().getFileName().toString().equals("sitl")?"SITL-":"")+p.getFileName();manifest.append(archiveName).append(" ").append(b.length).append(" ").append(DraftStore.hash(b)).append('\n');z.putNextEntry(new ZipEntry(archiveName));z.write(b);z.closeEntry();if(bytes.size()>LIMIT)throw new IOException("Archive bound");}z.putNextEntry(new ZipEntry("MANIFEST"));z.write(manifest.toString().getBytes(StandardCharsets.US_ASCII));z.closeEntry();}if(bytes.size()>LIMIT)throw new IOException("Archive bound");return bytes.toByteArray();}
 public void exported(byte[] archive,byte[] returned)throws IOException{if(!Arrays.equals(archive,returned))throw new IOException("Provider readback differs");String head=new String(unpack(archive).get("HEAD"),StandardCharsets.US_ASCII).trim();DraftStore.Snapshot s=store().load();if(s==null||!s.token.equals(head))throw new IOException("Head changed during export");DraftStore.Snapshot live=sitl().load();String archiveSitl=unpack(archive).containsKey("SITL-HEAD")?new String(unpack(archive).get("SITL-HEAD"),StandardCharsets.US_ASCII).trim():"ROOT";if(!(live==null?"ROOT":live.token).equals(archiveSitl))throw new IOException("SITL head changed during export");exported=exportIdentity87();exportSha=DraftStore.hash(archive);}
 public static Map<String,byte[]> unpack(byte[] bytes)throws IOException{if(bytes.length>LIMIT)throw new IOException("Archive bound");Map<String,byte[]> all=new TreeMap<>();int total=0;try(ZipInputStream z=new ZipInputStream(new ByteArrayInputStream(bytes))){ZipEntry e;while((e=z.getNextEntry())!=null){String n=e.getName();if(e.isDirectory()||!n.matches("HEAD|MANIFEST|(?:SITL-)?(?:HEAD|[0-9]{12}-[a-f0-9]{64}\\.bin)")||all.containsKey(n)||all.size()>2*DraftStore.MAX_RECORDS+2)throw new IOException("Archive entry");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int k;while((k=z.read(b))!=-1){total+=k;if(total>LIMIT||out.size()+k>DraftStore.MAX_BODY+65536)throw new IOException("Expanded bound");out.write(b,0,k);}all.put(n,out.toByteArray());}}byte[] m=all.remove("MANIFEST");if(m==null||!all.containsKey("HEAD"))throw new IOException("Manifest missing");String[] rows=new String(m,StandardCharsets.US_ASCII).split("\n");if(rows.length!=all.size()+3||!rows[0].equals("AERISARCHIVE83")||!rows[1].matches("[a-f0-9]{64}")||!rows[2].equals("authority=false")||!new String(all.get("HEAD"),StandardCharsets.US_ASCII).equals(rows[1]+"\n"))throw new IOException("Manifest schema");Set<String> seen=new HashSet<>();for(int i=3;i<rows.length;i++){String[] f=rows[i].split(" ");byte[] b=f.length==3?all.get(f[0]):null;if(b==null||!seen.add(f[0])||!Integer.toString(b.length).equals(f[1])||!DraftStore.hash(b).equals(f[2]))throw new IOException("Manifest digest");}return all;}
 public DraftStore.Snapshot stage(byte[] bytes)throws IOException{return stageWithId("w-"+UUID.randomUUID(),bytes);}
 public DraftStore.Snapshot stageWithId(String id,byte[] bytes)throws IOException{validId(id);if(!id.startsWith("w-"))throw new IOException("Staging id");admit();Map<String,byte[]> files=unpack(bytes);if(staged!=null)throw new IOException("Pending import retained; restart before another");if(root.toFile().getUsableSpace()<DraftStore.RESERVE+2L*LIMIT)throw new IOException("Import reserve");Path p=root.resolve(id);Files.createDirectory(p);for(Map.Entry<String,byte[]>e:files.entrySet()){String name=e.getKey();Path dest=name.startsWith("SITL-")?p.resolve("sitl").resolve(name.substring(5)):p.resolve(name);Files.createDirectories(dest.getParent());put(dest,e.getValue());}if(files.containsKey("SITL-HEAD"))new DraftStore(p.resolve("sitl")).load();syncDir(p);DraftStore.Snapshot s=new DraftStore(p).load();if(s==null)throw new IOException("Empty imported head");staged=id;stagedDigest=DraftStore.hash(bytes);return s;}
 public DraftStore.Snapshot reconcileStage(String id,byte[] bytes)throws IOException{validId(id);Map<String,byte[]>files=unpack(bytes);Path p=root.resolve(id);if(!Files.isDirectory(p)||Files.isSymbolicLink(p))throw new IOException("Original staging missing");for(Map.Entry<String,byte[]>e:files.entrySet()){String n=e.getKey();Path f=n.startsWith("SITL-")?p.resolve("sitl").resolve(n.substring(5)):p.resolve(n);if(Files.isSymbolicLink(f)||!Files.isRegularFile(f)||!Arrays.equals(Files.readAllBytes(f),e.getValue()))throw new IOException("Original staging incomplete/different; retained");}DraftStore.Snapshot snap=new DraftStore(p).load();if(snap==null)throw new IOException("Missing staging head");staged=id;stagedDigest=DraftStore.hash(bytes);return snap;}
 public String stagedId(){return staged;}public String stagedSha(){return stagedDigest;}
 public void activate(String sha)throws IOException{if(staged==null||!Objects.equals(sha,stagedDigest))throw new IOException("Explicit staged digest required");new DraftStore(root.resolve(staged)).load();select(staged);staged=null;stagedDigest=null;exported=null;}
 private String exportIdentity87()throws IOException{DraftStore.Snapshot a=store().load(),b=sitl().load();return selected+":"+(a==null?"ROOT":a.token)+":"+(b==null?"ROOT":b.token);}
 public void fresh()throws IOException{admit();DraftStore.Snapshot h=store().load();if((h!=null||sitl().load()!=null)&&!exportIdentity87().equals(exported))throw new IOException("Verified export of current head required");String id="w-"+UUID.randomUUID();new DraftStore(root.resolve(id));select(id);exported=null;}
 private void select(String id)throws IOException{validId(id);Path pending=root.resolve("CURRENT.pending");if(Files.exists(pending))throw new IOException("Pending selection retained");put(pending,(id+"\n").getBytes(StandardCharsets.US_ASCII));syncDir(root);Files.move(pending,root.resolve("CURRENT"),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);syncDir(root);selected=id;}
}
